#include <iostream>

int main() {
    int count = 0;
    // Print numbers between 1 and 60 divisible by 3 and 4 (i.e. divisible by 12)
    for (int i = 1; i <= 60; ++i) {
        if (i % 3 == 0 && i % 4 == 0) {
            std::cout << i;
            ++count;
            if (count % 3 == 0) {
                std::cout << '\n';
            } else {
                std::cout << ' ';
            }
        }
    }
    return 0;
}

#include <iostream>
#include <iomanip>

int main() {
    const int n = 50000;

    // Sum left to right using float to clearly illustrate precision loss
    float sum_left = 0.0f;
    for (int i = 1; i <= n; ++i) {
        sum_left += 1.0f / static_cast<float>(i);
    }

    // Sum right to left
    float sum_right = 0.0f;
    for (int i = n; i >= 1; --i) {
        sum_right += 1.0f / static_cast<float>(i);
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << "Left-to-right sum:  " << sum_left << '\n';
    std::cout << "Right-to-left sum: " << sum_right << '\n';
    return 0;
}

#include <iostream>
#include <iomanip>

int main() {
    const double x = 1.0;
    double sum = 1.0;  // Initial term for n = 0
    double item = 1.0; // Current term

    for (int n = 1; n <= 15; ++n) {
        item = item * x / n;
        sum += item;
    }

    std::cout << std::fixed << std::setprecision(10);
    std::cout << "Approximated e^1.0: " << sum << '\n';
    return 0;
}
